import{_ as n,o as t,c as i,a0 as r}from"./chunks/framework.BMIT1c_r.js";const h=JSON.parse('{"title":"2. Insightful Limits Reveal Fundamental Behavior","description":"","frontmatter":{},"headers":[],"relativePath":"tractable-limits.md","filePath":"tractable-limits.md"}'),a={name:"tractable-limits.md"};function o(s,e,l,m,g,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-insightful-limits-reveal-fundamental-behavior" tabindex="-1">2. Insightful Limits Reveal Fundamental Behavior <a class="header-anchor" href="#_2-insightful-limits-reveal-fundamental-behavior" aria-label="Permalink to &quot;2. Insightful Limits Reveal Fundamental Behavior&quot;">​</a></h1><blockquote><p>&quot;Appropriate asymptotic perspectives often render otherwise intractable systems analytically tractable.&quot; Modern deep learning systems regularly involve hundreds of interacting architectural components comprised of hundreds of billions of parameters trained on trillions of tokens. Constructing microscopic theories that track every individual parameter in such practical setups seems all but hopeless. Fortunately, complex systems often simplify when approximated as effectively infinite in size, revealing simple mathematical structures that remain deeply informative for original finite systems.</p></blockquote><h2 id="a-the-infinite-width-limit-the-lazy-rich-dichotomy" tabindex="-1">A. The Infinite Width Limit &amp; The Lazy/Rich Dichotomy <a class="header-anchor" href="#a-the-infinite-width-limit-the-lazy-rich-dichotomy" aria-label="Permalink to &quot;A. The Infinite Width Limit &amp; The Lazy/Rich Dichotomy&quot;">​</a></h2><p><em>Focuses on mean-field behaviors when the number of neurons in hidden layers approaches infinity, separating frozen feature kernels from adaptive representation learning.</em></p><ul><li><strong>Neal [1996]</strong> — <em>Priors for infinite networks</em></li><li><strong>Poole et al. [2016]</strong> — <em>Exponential expressivity in deep neural networks through transient chaos</em></li><li><strong>Lecun et al. [1998]</strong> — <em>Gradient-based learning applied to document recognition</em></li><li><strong>Jacot et al. [2018]</strong> — <em>Neural tangent kernel: Convergence and generalization in neural networks</em></li><li><strong>Lee et al. [2019]</strong> — <em>Wide neural networks of any depth evolve as linear models under gradient descent</em></li><li><strong>Chizat et al. [2019]</strong> — <em>On lazy training in differentiable programming</em></li><li><strong>Mei et al. [2019]</strong> — <em>Mean-field theory of two-layers neural networks: dimension-free bounds and kernel limit</em></li><li><strong>Rotskoff &amp; Eric Vanden-Eijnden [2018]</strong> — <em>Parameters as interacting particles: long time convergence and asymptotic error scaling of neural networks</em></li><li><strong>Chizat &amp; Bach [2018]</strong> — <em>On the global convergence of gradient descent for over-parameterized models using optimal transport</em></li><li><strong>Bordelon &amp; Pehlevan [2022]</strong> — <em>Self-consistent dynamical field theory of kernel evolution in wide neural networks</em></li><li><strong>Aubin et al. [2018]</strong> — <em>The committee machine: Computational to statistical gaps in learning a two-layers neural network</em></li><li><strong>Goldt et al. [2019]</strong> — <em>Dynamics of stochastic gradient descent for two-layer neural networks in the teacher-student setup</em></li><li><strong>Ren et al. [2025]</strong> — <em>Emergence and scaling laws in sgd learning of shallow neural networks</em></li><li><strong>Abbe et al. [2022]</strong> — <em>The merged-staircase property: a necessary and nearly sufficient condition for sgd learning of sparse functions on two-layer neural networks</em></li><li><strong>Moniri et al. [2023]</strong> — <em>A theory of non-linear feature learning with one gradient step in two-layer neural networks</em></li><li><strong>Cui et al. [2024]</strong> — <em>Asymptotics of feature learning in two-layer networks after one gradient-step</em></li><li><strong>Defilippis et al. [2025]</strong> — <em>Scaling laws and spectra of shallow neural networks in the feature learning regime</em></li><li><strong>Montanari &amp; Wang [2026]</strong> — <em>Phase transitions for feature learning in neural networks</em></li><li><strong>Saxe [2015]</strong> — <em>Deep linear neural networks: A theory of learning in the brain and mind</em></li><li><strong>Atanasov et al. [2021]</strong> — <em>Neural networks as kernel learners: The silent alignment effect</em></li><li><strong>Atanasov et al. [2025]</strong> — <em>The optimization landscape of sgd across the feature learning strength</em></li><li><strong>Maennel et al. [2018]</strong> — <em>Gradient descent quantizes relu network features</em></li><li><strong>Woodworth et al. [2020]</strong> — <em>Kernel and rich regimes in overparametrized models</em></li></ul><h3 id="the-bayesian-perspective" tabindex="-1">The Bayesian Perspective <a class="header-anchor" href="#the-bayesian-perspective" aria-label="Permalink to &quot;The Bayesian Perspective&quot;">​</a></h3><ul><li><strong>Lee et al. [2017]</strong> — <em>Deep neural networks as gaussian processes</em></li><li><strong>Cohen et al. [2021b]</strong> — <em>Learning curves for overparametrized deep neural networks: A field theory perspective</em></li><li><strong>Lavie et al. [2024]</strong> — <em>Towards understanding inductive bias in transformers: A view from infinity</em></li><li><strong>Seroussi et al. [2023]</strong> — <em>Separation of scales and a thermodynamic description of feature learning in some cnns</em></li><li><strong>Rubin et al. [2023]</strong> — <em>Grokking as a first order phase transition in two layer networks</em></li><li><strong>Rubin et al. [2025b]</strong> — <em>From kernels to features: A multi-scale adaptive theory of feature learning</em></li><li><strong>Rubin et al. [2025a]</strong> — <em>Mitigating the curse of detail: Scaling arguments for feature learning and sample complexity</em></li><li><strong>Yang et al. [2023a]</strong> — <em>A theory of representation learning gives a deep generalisation of kernel methods</em></li></ul><hr><h2 id="b-special-focus-the-tensor-programs-framework-μp" tabindex="-1">B. Special Focus: The Tensor Programs Framework &amp; µP <a class="header-anchor" href="#b-special-focus-the-tensor-programs-framework-μp" aria-label="Permalink to &quot;B. Special Focus: The Tensor Programs Framework &amp; µP&quot;">​</a></h2><p><em>Highlights the structural infinite-width and depth scaling theories that formulate Maximal Update Parameterization, safeguarding zero-shot hyperparameter transfer across massive target coordinates.</em></p><ul><li><strong>Yang &amp; Hu [2021]</strong> — <em>Tensor programs iv: Feature learning in infinite-width neural networks</em></li><li><strong>Yang &amp; Littwin [2023]</strong> — <em>Tensor programs ivb: Adaptive optimization in the infinite-width limit</em></li><li><strong>Yang et al. [2022]</strong> — <em>Tensor programs v: Tuning large neural networks via zero-shot hyperparameter transfer</em></li><li><strong>Noci et al. [2024]</strong> — <em>Super consistency of neural network landscapes and learning rate transfer</em></li><li><strong>Ghosh et al. [2025]</strong> — <em>Understanding the mechanisms of fast hyperparameter transfer</em></li><li><strong>Hayou [2025]</strong> — <em>A proof of learning rate transfer under mu p</em></li></ul><hr><h2 id="c-the-infinite-depth-limit-alternative-structural-directions" tabindex="-1">C. The Infinite Depth Limit &amp; Alternative Structural Directions <a class="header-anchor" href="#c-the-infinite-depth-limit-alternative-structural-directions" aria-label="Permalink to &quot;C. The Infinite Depth Limit &amp; Alternative Structural Directions&quot;">​</a></h2><p><em>Focuses on continuous limits where networks approximate Differential Equations, alongside scaling rules tailored for multi-head attention blocks and mixture-of-experts.</em></p><ul><li><strong>Bordelon et al. [2024b]</strong> — <em>Infinite limits of multi-head transformer dynamics</em></li><li><strong>Lénaïc Chizat [2025]</strong> — <em>The hidden width of deep resnets: Tight error bounds and phase diagrams</em></li><li><strong>Chaintron et al. [2026]</strong> — <em>Resnets of all shapes and sizes: Convergence of training dynamics in the large-scale limit</em></li><li><strong>Ricky TQ Chen et al. [2018]</strong> — <em>Neural ordinary differential equations</em></li><li><strong>Bordelon et al. [2023]</strong> — <em>Depthwise hyperparameter transfer in residual networks: Dynamics and scaling limit</em></li><li><strong>Yang et al. [2023b]</strong> — <em>Tensor programs vi: Feature learning in infinite-depth neural networks</em></li><li><strong>Dey et al. [2025]</strong> — <em>Don&#39;t be lazy: Completep enables compute-efficient deep transformers</em></li><li><strong>Clark et al. [2026]</strong> — <em>Structure, disorder, and dynamics in task-trained recurrent neural circuits</em></li><li><strong>Bauer et al. [2026]</strong> — <em>A unified theory of feature learning in rnns and dnns</em></li><li><strong>Hron et al. [2020]</strong> — <em>Infinite attention: Nngp and ntk for deep attention networks</em></li><li><strong>Małaśnicki et al. [2025]</strong> — <em>µ-parameterization for mixture of experts</em></li><li><strong>Jiang et al. [2026]</strong> — <em>Hyperparameter transfer with mixture-of-expert layers</em></li></ul><hr><h2 id="d-joint-scaling-limits" tabindex="-1">D. Joint Scaling Limits <a class="header-anchor" href="#d-joint-scaling-limits" aria-label="Permalink to &quot;D. Joint Scaling Limits&quot;">​</a></h2><p><em>Focuses on high-dimensional random matrix regimes where sample capacity and parameter sizes approach infinity concurrently under controlled scaling fractions.</em></p><ul><li><strong>Seung et al. [1992]</strong> — <em>Statistical mechanics of learning from examples</em></li><li><strong>Saad &amp; Solla [1995]</strong> — <em>Exact solution for on-line learning in multilayer neural networks</em></li><li><strong>Lenka Zdeborová &amp; Florent Krzakala [2016]</strong> — <em>Statistical physics of inference: Thresholds and algorithms</em></li><li><strong>Qianyi Li &amp; Haim Sompolinsky [2021]</strong> — <em>Statistical mechanics of deep linear neural networks: The backpropagating kernel renormalization</em></li><li><strong>Hoffmann et al. [2022]</strong> — <em>Training compute-optimal large language models</em></li><li><strong>Bordelon &amp; Pehlevan [2025]</strong> — <em>Deep linear network training dynamics from random initialization: Data, width, depth, and hyperparameter transfer</em></li><li><strong>Hayou &amp; Yang [2023]</strong> — <em>Width and depth limits commute in residual networks</em></li></ul><hr><h2 id="e-the-discretization-hypothesis-finite-size-corrections" tabindex="-1">E. The Discretization Hypothesis &amp; Finite-Size Corrections <a class="header-anchor" href="#e-the-discretization-hypothesis-finite-size-corrections" aria-label="Permalink to &quot;E. The Discretization Hypothesis &amp; Finite-Size Corrections&quot;">​</a></h2><p><em>Evaluates the structural boundaries where noisy, finite neural structures drift from continuous infinite reference horizons.</em></p><ul><li><strong>Hanin &amp; Nica [2019]</strong> — <em>Finite depth and width corrections to the neural tangent kernel</em></li><li><strong>Li et al. [2022]</strong> — <em>The neural covariance sde: Shaped infinite depth-and-width networks at initialization</em></li><li><strong>Noci et al. [2023]</strong> — <em>The shaped transformer: Attention models in the infinite depth-and-width limit</em></li><li><strong>Hanin &amp; Tianze Jiang [2025]</strong> — <em>Global universality of singular values in products of many large random matrices</em></li><li><strong>Mandt et al. [2017]</strong> — <em>Stochastic gradient descent as approximate bayesian inference</em></li><li><strong>Jastrzebski et al. [2017]</strong> — <em>Three factors influencing minima in sgd</em></li><li><strong>Daniel A Roberts et al. [2022]</strong> — <em>The principles of deep learning theory</em></li><li><strong>Jacob Zavatone-Veth et al. [2021]</strong> — <em>Asymptotics of representation learning in finite bayesian neural networks</em></li><li><strong>Segadlo et al. [2022]</strong> — <em>Unified field theoretical approach to deep and recurrent neuronal networks</em></li><li><strong>Bordelon &amp; Pehlevan [2023]</strong> — <em>Dynamics of finite width kernel and prediction fluctuations in mean field neural networks</em></li><li><strong>Glasgow et al. [2025]</strong> — <em>Propagation of chaos in one-hidden-layer neural networks beyond logarithmic time</em></li></ul>',23)])])}const p=n(a,[["render",o]]);export{h as __pageData,p as default};
